package com.whatsaas.automation.engine;
import com.fasterxml.jackson.databind.*; import com.whatsaas.automation.domain.*; import com.whatsaas.automation.infrastructure.*; import java.time.*; import java.util.*; import java.util.function.Function; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class WorkflowExecutionEngine{private final WorkflowVersionRepository versions;private final WorkflowExecutionRepository executions;private final WorkflowStepRepository steps;private final ObjectMapper mapper;private final Map<String,WorkflowNodeProcessor> processors;
 public WorkflowExecutionEngine(WorkflowVersionRepository v,WorkflowExecutionRepository e,WorkflowStepRepository s,ObjectMapper m,List<WorkflowNodeProcessor> p){versions=v;executions=e;steps=s;mapper=m;processors=p.stream().collect(java.util.stream.Collectors.toMap(WorkflowNodeProcessor::type,Function.identity()));}
 @Transactional public void run(WorkflowExecution execution){try{WorkflowVersion version=versions.findById(execution.getVersionId()).orElseThrow();JsonNode graph=mapper.readTree(version.getGraphJson());JsonNode context=mapper.readTree(execution.getContextJson());String nodeId=execution.getCurrentNodeId();for(int guard=0;nodeId!=null&&guard<50;guard++){JsonNode node=node(graph,nodeId);String type=node.path("type").asText();if("trigger".equals(type)){nodeId=next(graph,nodeId,null);execution.advance(nodeId,mapper.writeValueAsString(context));continue;}WorkflowNodeProcessor processor=Optional.ofNullable(processors.get(type)).orElseThrow(()->new IllegalArgumentException("Unsupported node type "+type));NodeResult result=processor.process(execution,node,context);String target=next(graph,nodeId,result.branch());if(result.waitUntil()!=null){steps.save(new WorkflowStep(execution.getId(),nodeId,type,WorkflowStepStatus.WAITING,result.outputJson(),null,execution.getAttempts()+1));execution.waitUntil(target,result.waitUntil(),mapper.writeValueAsString(context));return;}steps.save(new WorkflowStep(execution.getId(),nodeId,type,WorkflowStepStatus.COMPLETED,result.outputJson(),null,execution.getAttempts()+1));nodeId=target;execution.advance(nodeId,mapper.writeValueAsString(context));}if(nodeId==null)execution.complete();else execution.fail("Workflow exceeded node safety limit.");}catch(Exception ex){steps.save(new WorkflowStep(execution.getId(),execution.getCurrentNodeId()==null?"unknown":execution.getCurrentNodeId(),"engine",WorkflowStepStatus.FAILED,null,ex.getMessage(),execution.getAttempts()+1));if(execution.getAttempts()<5)execution.retry(Instant.now().plusSeconds((long)Math.pow(2,execution.getAttempts()+1)*15),ex.getMessage());else execution.fail(ex.getMessage());}}
 @Scheduled(fixedDelayString="${app.automation.scheduler-delay:3000}") @Transactional public void resumeDue(){for(WorkflowExecution e:executions.findTop100ByStatusInAndNextRunAtLessThanEqualOrderByNextRunAtAsc(List.of(WorkflowExecutionStatus.WAITING,WorkflowExecutionStatus.RETRY_WAIT),Instant.now())){run(e);}}
 private JsonNode node(JsonNode g,String id){for(JsonNode n:g.path("nodes"))if(id.equals(n.path("id").asText()))return n;throw new IllegalArgumentException("Node missing "+id);} private String next(JsonNode g,String id,String branch){for(JsonNode e:g.path("edges"))if(id.equals(e.path("source").asText())&&(branch==null||branch.equals(e.path("data").path("branch").asText(e.path("sourceHandle").asText()))))return e.path("target").asText(null);return null;}
}
